cat >> test/app.test.ts <<'EOF'

test("/login returns the api_token for correct credentials, without a bearer token", async () => {
  const res = await fetch(`${base}/login`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email: "alice@example.com", password: "alice-password" }),
  });
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { token: "alice-token" });
});

test("/login rejects a wrong password and an unknown email with the same error", async () => {
  const post = (body: unknown) =>
    fetch(`${base}/login`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(body),
    });
  const wrong = await post({ email: "alice@example.com", password: "nope" });
  const unknown = await post({ email: "nobody@example.com", password: "alice-password" });
  assert.equal(wrong.status, 401);
  assert.equal(unknown.status, 401);
  assert.deepEqual(await wrong.json(), await unknown.json());
});

test("/login requires email and password strings", async () => {
  const res = await fetch(`${base}/login`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email: "alice@example.com" }),
  });
  assert.equal(res.status, 400);
});
EOF
